mapper.select:
SELECT COUNT(*)
FROM tb_course_question
WHERE course_no = #{courseNo}

mapper.insert:
INSERT INTO tb_course_question (
      course_no
    , writer_user_no
    , course_question_title
    , course_question_content
    , course_question_status
    , is_private
) VALUES (
      #{courseNo}
    , #{writerUserNo}
    , #{courseQuestionTitle}
    , #{courseQuestionContent}
    , 0
    , #{privatePost}
)

INSERT INTO tb_course_question_answer (
      course_question_no
    , writer_user_no
    , writer_role
    , answer_content
    , createdate
) VALUES (
      #{courseQuestionNo}
    , #{writerUserNo}
    , #{writerRole}
    , #{answerContent}
    , NOW()
)

mapper.select:
SELECT COUNT(*) > 0
FROM tb_course_question
WHERE course_question_no = #{courseQuestionNo}
  AND writer_user_no = #{userNo}

mapper.update:
UPDATE tb_course_question
SET
      course_question_title   = #{courseQuestionTitle}
    , course_question_content = #{courseQuestionContent}
    , is_private = #{privatePost}
WHERE course_question_no = #{courseQuestionNo}

mapper.select:
SELECT course_no
FROM tb_course_question
WHERE course_question_no = #{courseQuestionNo}

SELECT COUNT(*) > 0
FROM tb_course_question_answer
WHERE answer_no = #{answerNo}
  AND writer_user_no = #{profNo}
